{
  "title": "Disposition of $200 Barometer Gift",
  "setting": "National Park Service, speech on Federal lands policy, present time",
  "decider": "National Park Service employee",
  "agent_recast": false,
  "recast_note": "",
  "agent": "National Park Service employee",
  "agent_role": "decide",
  "situation": "A National Park Service employee delivered a speech on Federal lands policy. At the conclusion of the speech, a prohibited source presented the employee with a barometer valued at $200. The employee chose not to decline the gift in order to avoid public embarrassment. Under 5 CFR §2635.206(a)(1), the employee must dispose of gifts that cannot be accepted. The barometer’s market value exceeds $100, so destruction is not permitted. The employee may either return the barometer, reimburse the donor the market value, or seek agency approval to retain the gift if statutory authority allows acceptance.",
  "question": "What should the employee do with the $200 barometer gift?",
  "facts": [
    {
      "id": "F1",
      "kind": "situation",
      "status": "confirmed",
      "fact": "The employee works for the National Park Service.",
      "spans": ["src:72ad31f4a7f5#p1.202"]
    },
    {
      "id": "F2",
      "kind": "situation",
      "status": "confirmed",
      "fact": "The employee received a barometer worth $200 from a prohibited source after a speech.",
      "spans": ["src:72ad31f4a7f5#p1.202"]
    },
    {
      "id": "F3",
      "kind": "capability",
      "status": "confirmed",
      "fact": "The barometer’s market value exceeds $100.",
      "spans": ["src:72ad31f4a7f5#p1.202"]
    },
    {
      "id": "F4",
      "kind": "authority",
      "status": "confirmed",
      "fact": "Under §2635.206(a)(1), the employee must promptly return the tangible item or pay the donor its market value; destruction is prohibited when the market value exceeds $100.",
      "spans": ["src:72ad31f4a7f5#p1.200", "src:72ad31f4a7f5#p1.202"]
    },
    {
      "id": "F5",
      "kind": "authority",
      "status": "confirmed",
      "fact": "The agency may accept the gift if permitted under specific statutory gift‑acceptance authority.",
      "spans": ["src:72ad31f4a7f5#p1.202"]
    },
    {
      "id": "F6",
      "kind": "situation",
      "status": "confirmed",
      "fact": "The employee did not decline the gift to avoid public embarrassment.",
      "spans": ["src:72ad31f4a7f5#p1.202"]
    },
    {
      "id": "F7",
      "kind": "authority",
      "status": "confirmed",
      "fact": "Employees must dispose of gifts that cannot be accepted in accordance with the procedures set forth in §2635.206.",
      "spans": ["src:72ad31f4a7f5#p1.199"]
    }
  ],
  "options": {
    "O1": {
      "do": "Return the barometer to the donor promptly.",
      "move": "act",
      "irreversible": true
    },
    "O2": {
      "do": "Reimburse the donor $200 for the barometer’s market value.",
      "move": "act",
      "irreversible": true
    },
    "O3": {
      "do": "Ask the agency ethics official whether statutory authority permits the agency to accept the barometer and retain it.",
      "move": "ask",
      "irreversible": false,
      "to": "agency ethics official"
    }
  },
  "real_option": "O1",
  "authored_options": ["O2", "O3"]
}

